/* ============================================================
   SG Caribbean Transfers & Tours — Trilingual content (English / Español / Français)
   Purpose: translation dictionary + language switching.
   Exposes globals t(key, vars), getLang() for the feature modules
   (calculator.js, tours.js, cart.js, shell.js) to render dynamic content
   in the active language. The language comes from <html lang>, which
   tools/build-langs.py stamps on every page: /es/ and /fr/ are rendered
   ahead of time, so the URL decides, and the visible EN/ES/FR control is
   a set of links between those URLs rather than an in-place swap.
   Notifies listeners via the 'sariel:langchange' event on document.
   Loaded first, before all other js/ modules.
   ============================================================ */

