    'transfersAeo.lead': 'Private door-to-door transfers from every international airport in the Dominican Republic to Sosúa, Cabarete, Puerto Plata and Playa Dorada. Prices are fixed before you fly and paid in cash on arrival — Puerto Plata airport (POP) to Sosúa is US$23.95 for 1 to 6 guests.',
