    'transfersAeo.f5Value': 'Car (3) · Minivan (6) · Van (10) · Minibus (15)',
    'transfersFaq.heading': 'Transfer questions, <em>answered</em>',
    'transfersFaq.q1': 'How much is a transfer from Puerto Plata airport to Sosúa?',
    'transfersFaq.a1': 'US$23.95 one way for 1 to 6 guests in a private vehicle, plus US$5 for each extra passenger above six. The price is fixed before you travel.',
    'transfersFaq.q2': 'Which airports do you cover?',
    'transfersFaq.a2': 'We run fixed-price transfers from Puerto Plata (POP), Santiago (STI), Santo Domingo (SDQ), Punta Cana (PUJ) and Samaná El Catey (AZS). La Romana (LRM) and Barahona (BRX) are quoted on request.',
    'transfersFaq.q3': 'Do I have to pay in advance?',
    'transfersFaq.a3': 'No. Your reservation is confirmed on WhatsApp with nothing charged up front — you settle with the driver in cash, US dollars or Dominican pesos, at the end of the ride. Ask us if you would rather pay by card.',
    'transfersFaq.q4': 'What happens if my flight is delayed?',
    'transfersFaq.a4': 'You do not need to tell us. The flight number you send when booking is tracked in real time, and the pickup slides with it — two hours late means your driver shows up two hours later, and the price does not move.',
    'transfersFaq.q5': 'How many passengers fit in the vehicle?',
    'transfersFaq.a5': 'Four vehicle sizes, picked from your group: 3 guests in a car, 6 in a minivan, 10 in a van, 15 in a minibus. The calculator on this page upgrades you automatically once your passenger count outgrows the smaller option.',
    'transfersFaq.q6': 'Is there an extra charge for luggage?',
    'transfersFaq.a6': 'Up to 10 suitcases travel free. Above that a flat US$15 is added to that vehicle, because a trailer is needed. Surfboards or oversized bags — tell us and we plan for it.',

    'excursionsAeo.eyebrow': 'The short version',
