    'excursionsAeo.lead': 'Six private day tours across the north coast of the Dominican Republic, with hotel pickup in Sosúa, Puerto Plata and Cabarete and round-trip transport always included. Every excursion is your group only — no strangers, no bus waiting to fill up. Minimum group size is 4 guests.',
