    'excursionsFaq.heading': 'Excursion questions, <em>answered</em>',
    'excursionsFaq.q1': 'Are the excursions private?',
    'excursionsFaq.a1': 'Always. There is no shared option — you book the whole vehicle and the whole guide. That is why departure times are yours to set and why a tour can be cut short or stretched out on the day without asking anyone else.',
    'excursionsFaq.q2': 'What is the minimum group size?',
    'excursionsFaq.a2': 'Four guests on every tour. Below that we can still quote you privately on WhatsApp, but the listed prices start at four.',
    'excursionsFaq.q3': 'Is transport included?',
    'excursionsFaq.a3': 'Yes. Round-trip private transport from your hotel, villa or Airbnb in Sosúa, Puerto Plata or Cabarete is included in every excursion price.',
    'excursionsFaq.q4': 'What if we are more than six people?',
    'excursionsFaq.a4': 'Type your group size into the field on any tour card. If that number is priced, it shows instantly; if not, the card switches to "Ask for a Quote" and we price it for you on WhatsApp rather than guessing.',
    'excursionsFaq.q5': 'Which tour do most people book?',
    'excursionsFaq.a5': 'Charcos de Damajagua — limestone pools you climb up, then jump and slide back down. Punta Rusia and the Puerto Plata City Tour come next.',
    'excursionsFaq.q6': 'Can you pick us up from a cruise ship instead?',
    'excursionsFaq.a6': 'Yes. Pickups from Amber Cove and Taino Bay are planned around your ship\'s all-aboard time — see our cruise shore excursions page.',

    'cruisesAeo.eyebrow': 'The short version',
    'cruisesAeo.heading': 'Amber Cove and Taino Bay shore excursions, <em>at a glance</em>',
    'cruisesAeo.lead': 'Private shore excursions for cruise passengers docking at Amber Cove (Maimón) and Taino Bay (Puerto Plata). We meet you outside the terminal gate, build the day backwards from your ship\'s all-aboard time, and return you to the pier with a margin. A typical Puerto Plata port call runs 8 to 9 hours.',
    'cruisesAeo.f1Label': 'Piers served',
