    'cruisesAeo.f4Label': 'Return to ship',
    'cruisesAeo.f4Value': 'Guaranteed before all-aboard',
    'cruisesAeo.f5Label': 'Group',
    'cruisesAeo.f5Value': '100% private · from 4 guests',
    'cruisesFaq.heading': 'Cruise questions, <em>answered</em>',
    'cruisesFaq.q1': 'Which cruise ports do you pick up from?',
    'cruisesFaq.a1': 'Both of Puerto Plata\'s terminals: Amber Cove in Maimón and Taino Bay in Puerto Plata city. We meet you outside the terminal gate with a name sign.',
    'cruisesFaq.q2': 'Will I be back before my ship leaves?',
    'cruisesFaq.a2': 'Yes. We track your ship\'s departure and plan every tour backwards from its all-aboard time, returning you to the pier with a margin rather than on the dot.',
    'cruisesFaq.q3': 'How long is a typical Puerto Plata port call?',
    'cruisesFaq.a3': 'Usually 8 to 9 hours. Our shore excursions are half-day trips, which leaves several hours of margin even after the drive each way.',
    'cruisesFaq.q4': 'How far is Sosúa from the cruise piers?',
    'cruisesFaq.a4': 'About 50 minutes from Taino Bay and 60 minutes from Amber Cove.',
    'cruisesFaq.q5': 'Are cruise excursions private?',
    'cruisesFaq.a5': 'Yes — your group only, in your own vehicle, at your own pace. You are never grouped with passengers from other ships.',
    'cruisesFaq.q6': 'Can we build our own itinerary for the day?',
    'cruisesFaq.a6': 'Yes. Tell us your ship, your port and what you want to see, and we plan a custom day around your all-aboard time instead of a fixed package.',


