    'cruise1.title': 'Charcos de Damajagua',
    'cruise1.desc': "Limestone pools you climb up, then jump and slide back down. About an hour from either pier, so it sits comfortably inside a normal port call. Bring swimwear and shoes you don't mind soaking.",
    'cruise1.duration': 'Half day',
    'cruise2.title': 'Puerto Plata City Tour',
    'cruise2.desc': 'The shortest run from either pier — Taino Bay is inside the city itself. Fort San Felipe, the Victorian old town, the cable car up Pico Isabel de Torres, and amber, rum and cacao tastings. The one to pick when your ship has a short call. US$65 per person, up to 6 guests.',
    'cruise2.duration': 'Half day',
    'cruise4.title': 'ATV Adventure',
    'cruise4.desc': 'Your own quad on country trails, river crossings and back roads behind Puerto Plata. Roughly half an hour from Amber Cove or Taino Bay — dusty, loud, and done in half a day with the afternoon still yours.',
    'cruise4.duration': 'Half day',
    'cruise5.title': 'Dune Buggy Adventure',
    'cruise5.desc': 'The same backcountry as the quads, but side by side under a roll cage — easier if you would rather share the driving. About half an hour from either pier, and planned backwards from your all-aboard time.',
    'cruise5.duration': 'Half day',

