    'why.heading': 'What sets us apart',
    'why.lead': 'At SG Caribbean Transfers &amp; Tours, we believe a tour is much more than getting people from one place to another. Our mission is to make every visitor live a safe, comfortable and authentic experience from the first contact to the end of their adventure.',
    'why.card1Title': 'Safe &amp; Reliable Service',
    'why.card1Desc': 'Your safety and peace of mind are our priority throughout the journey.',
    'why.card2Title': 'Local Knowledge',
    'why.card2Desc': 'We know Sosúa, Cabarete, Puerto Plata and the region\'s top destinations inside out, so we can recommend the best places and experiences.',
