    'faq.eyebrow': 'Good to know',
    'faq.heading': 'Questions, <em>answered</em>',
    'faq.q1': 'Do you provide child seats?',
    'faq.a1': "Yes — child and booster seats are available free of charge. Just tell us the ages of your little ones when you book and we'll have the right seats installed before pickup.",
    'faq.q2': 'Can I pay on arrival?',
    'faq.a2': 'Yes. No prepayment is needed to confirm your reservation — you pay your driver in cash (USD or Dominican pesos) when we meet you. Card payment is available on request.',
    'faq.q3': 'How many passengers fit in the vehicle?',
    'faq.a3': "Private cars seat up to 3 guests, minivans up to 6, vans up to 10 and minibuses up to 15 — all with space for standard luggage. Traveling with surfboards or extra bags? Tell us and we'll plan for it.",
    'faq.q4': 'What happens if my flight is delayed?',
    'faq.a4': 'Nothing changes for you. We monitor your flight number in real time and adjust the pickup automatically — your driver will be waiting whenever you land, at no extra cost.',
    'faq.q5': 'Are excursions private?',
    'faq.a5': 'Completely. Every excursion is just your group — your own vehicle, your own guide, your own schedule. No strangers, no waiting for a bus to fill up.',
    'faq.q6': 'Do you operate at night and on weekends?',
    'faq.a6': 'Yes — we run 24 hours a day, every day of the year. Early-morning departures, late-night landings, Sundays and holidays are all normal for us: tell us your flight time and a driver will be there.',

