    'sosua.hero.eyebrow': 'Sosúa · Puerto Plata · Dominican Republic',
    'sosua.hero.title': 'Getting to Sosúa, <em>sorted before you land</em>',
    'sosua.hero.lead': 'Puerto Plata airport is 15 minutes away. The cruise piers are 50. Whichever way you arrive, a local driver is already waiting — at a price agreed before you leave home.',

    'sosua.answer.eyebrow': 'The short version',
    'sosua.answer.heading': 'How to get to Sosúa, <em>in 30 seconds</em>',
    'sosua.answer.lead': 'Sosúa is a beach town on the north coast of the Dominican Republic, in the province of Puerto Plata. The closest airport is Gregorio Luperón International (POP), roughly 9 km away — about a 15-minute drive. SG Caribbean Transfers &amp; Tours runs private door-to-door transfers from POP to Sosúa at a fixed US$23.95 for 1 to 6 guests, with no prepayment: you pay your driver in cash when you arrive.',
    'sosua.answer.f1Label': 'Nearest airport',
    'sosua.answer.f1Value': 'Puerto Plata (POP) — 9 km, ~15 min',
    'sosua.answer.f2Label': 'Fixed transfer price',
    'sosua.answer.f2Value': 'US$23.95 one way, 1–6 guests',
    'sosua.answer.f3Label': 'Nearest cruise piers',
    'sosua.answer.f3Value': 'Taino Bay ~50 min · Amber Cove ~60 min',
    'sosua.answer.f4Label': 'Region',
    'sosua.answer.f4Value': 'Puerto Plata province, Dominican Republic',
    'sosua.answer.f5Label': 'Payment',
    'sosua.answer.f5Value': 'Cash on arrival — US dollars or Dominican pesos',
    'sosua.answer.f6Label': 'Driver languages',
    'sosua.answer.f6Value': 'English · Español',

