    'sosua.air.heading': 'Every airport to Sosúa, <em>with the real price</em>',
    'sosua.air.lead': 'These are the fares we actually charge, not estimates. Each one covers a private vehicle for up to 6 guests, one way, door to door.',
    'sosua.air.caption': 'One-way private transfer fares to Sosúa, for 1 to 6 guests',
