    'sosua.air.pujName': 'Punta Cana Intl.',
    'sosua.air.pujKm': '~300 km',
    'sosua.air.pujTime': '~4 h 45',
    'sosua.air.note': 'Add US$5 per passenger above six. Distances and drive times are approximate and depend on traffic and your exact address in Sosúa. Prices are per vehicle, not per person.',
    'sosua.air.stepsHeading': 'What happens on the day you land',
    'sosua.air.step1Title': 'You send us the flight number',
    'sosua.air.step1Body': 'One WhatsApp message is enough — no account, no form, no card details. We reply with the price confirmed in writing.',
    'sosua.air.step2Title': 'We watch the flight, not the clock',
    'sosua.air.step2Body': 'If you land two hours late, the pickup moves two hours later. Your driver waits at no extra cost — delays are our problem, not yours.',
    'sosua.air.step3Title': 'Name sign at arrivals, then straight to your door',
    'sosua.air.step3Body': 'Your driver meets you inside with a sign, helps with the luggage and drives you to your hotel, villa or Airbnb in Sosúa. Ask for a supermarket or ATM stop on the way and it costs nothing extra.',
    'sosua.air.cta': 'See all transfer prices',
    'sosua.air.ctaAlt': 'Quote another destination',

    'sosua.cruise.eyebrow': 'Arriving by cruise ship',
    'sosua.cruise.heading': 'Sosúa is <em>an easy half-day</em> from either pier',
    'sosua.cruise.lead': "Both of Puerto Plata's cruise terminals are about an hour from Sosúa, which makes the beach a comfortable independent excursion — not a rush.",
    'sosua.cruise.tainoTitle': 'Taino Bay → Sosúa',
    'sosua.cruise.tainoMeta': '~27 km · ~50 min',
    'sosua.cruise.tainoBody': 'Taino Bay sits right in Puerto Plata city, so you are on the coastal highway within minutes of stepping off the ship. We meet you outside the terminal gate.',
    'sosua.cruise.amberTitle': 'Amber Cove → Sosúa',
    'sosua.cruise.amberMeta': '~32 km · ~60 min',
    'sosua.cruise.amberBody': 'Amber Cove is in Maimón, just west of Puerto Plata. The drive to Sosúa follows the same coast road, past Playa Dorada and the airport turn-off.',
    'sosua.cruise.timingTitle': 'The all-aboard maths, done for you',
    'sosua.cruise.timingBody': "A typical Puerto Plata port call lasts 8 to 9 hours. A round trip to Sosúa uses roughly 2 hours of that in driving, which still leaves you six hours or more on the ground. We plan every cruise day backwards from your ship's all-aboard time and return you to the pier with a margin, never on the dot.",
    'sosua.cruise.cta': 'See cruise shore excursions',
    'sosua.cruise.ctaAlt': 'Ask for a cruise-day quote',

    'sosua.compare.eyebrow': 'Why book us instead',
    'sosua.compare.heading': 'Four ways to get to Sosúa. <em>Here is the honest comparison.</em>',
