    'cabarete.compare.lateRental': 'The desk may already be closed',
    'cabarete.compare.rowWho': 'Who is in the vehicle',
    'cabarete.compare.whoUs': 'Only your group, in a private air-conditioned van',
    'cabarete.compare.whoTaxi': 'Only your group',
    'cabarete.compare.whoShuttle': 'Whoever else booked that run',
    'cabarete.compare.whoRental': 'You, driving',
    'cabarete.compare.rowStops': 'Boards and bulky luggage',
    'cabarete.compare.stopsUs': 'Tell us the count and we send a van that fits them — no surcharge',
    'cabarete.compare.stopsTaxi': 'Depends entirely on the car that turns up',
    'cabarete.compare.stopsShuttle': 'Often refused or charged as an extra seat',
    'cabarete.compare.stopsRental': 'Only if you booked the right size of car',
    'cabarete.compare.rowPay': 'Paying',
    'cabarete.compare.payUs': 'Cash on arrival in US dollars or pesos — nothing up front',
    'cabarete.compare.payTaxi': 'Cash, rate agreed on the spot',
    'cabarete.compare.payShuttle': 'Usually prepaid online',
    'cabarete.compare.payRental': 'Card, plus a security deposit held',
    'cabarete.compare.rowSeats': 'Child seats',
    'cabarete.compare.seatsUs': 'Free — tell us the ages and they are fitted before pickup',
    'cabarete.compare.seatsTaxi': 'Rarely available',
    'cabarete.compare.seatsShuttle': 'Rarely available',
    'cabarete.compare.seatsRental': 'A paid add-on',
    'cabarete.compare.note': 'One more thing that does not fit in a table: we live here. Saul, Sariel, Luis and Leuris drive this coast every day, speak English and Spanish, and will tell you honestly whether the wind is worth carrying your gear down to Kite Beach this afternoon.',
    'cabarete.compare.cta': 'Meet the drivers',
    'cabarete.spots.eyebrow': 'Once you are here',
    'cabarete.spots.heading': 'What is <em>within reach of Cabarete</em>',
    'cabarete.spots.lead': 'Cabarete is one long street between the beach and the hills, which makes it walkable and keeps everything else close. These are the places our guests actually ask us to take them to.',
    'cabarete.spots.s1Name': 'Kite Beach',
    'cabarete.spots.s1Meta': 'Kitesurfing',
    'cabarete.spots.s1Body': 'Just west of town, and the reason Cabarete is on the world map. The bay funnels the trade wind straight across the water, the wind builds through the day, and by the afternoon the sky is full of kites. Worth going even if you never leave the sand.',
    'cabarete.spots.s2Name': 'Playa Encuentro',
    'cabarete.spots.s2Meta': 'Surf break',
    'cabarete.spots.s2Body': 'The surf break of the north coast, on the road between Cabarete and Sosúa. Mornings are the session — the water is cleanest and the wind has not arrived yet. Several surf schools work the beach if you have never stood up before.',
    'cabarete.spots.s3Name': 'Cabarete Bay',
    'cabarete.spots.s3Meta': 'In town',
    'cabarete.spots.s3Body': 'The town beach itself: windsurfers in the afternoon, and a row of restaurants that put their tables directly on the sand once the sun goes down. Everything Cabarete does in the evening happens along this strip.',
    'cabarete.spots.s4Name': 'El Choco National Park &amp; the caves',
    'cabarete.spots.s4Meta': 'Nature reserve',
    'cabarete.spots.s4Body': 'Behind the town, a lagoon and a set of limestone caves with clear pools you can swim in, inside a protected reserve of forest and birdlife. It is the standard plan for a day with no wind, and cool enough to be a relief at midday.',
    'cabarete.spots.s5Name': 'Sosúa',
    'cabarete.spots.s5Meta': 'Neighbouring town',
    'cabarete.spots.s5Body': 'The calm alternative, the next town west along the coast road: a reef-sheltered horseshoe bay where you can snorkel straight from the sand, plus the small museum that tells how the town was founded by Jewish refugees in 1940. <a href="sosua.html">See the full Sosúa guide</a>.',
    'cabarete.spots.s6Name': 'Charcos de Damajagua',
    'cabarete.spots.s6Meta': 'Full-day excursion',
    'cabarete.spots.s6Body': 'Limestone pools you climb up and then jump and slide back down. The single most requested excursion from this coast, and the one people talk about for years afterwards.',
    'cabarete.spots.cta': 'Browse private excursions',
    'cabarete.faq.heading': 'Cabarete questions, <em>answered</em>',
    'cabarete.faq.q1': 'Where exactly is Cabarete?',
    'cabarete.faq.a1': 'On the north coast of the Dominican Republic, in the province of Puerto Plata, on the coastal highway just east of Sosúa. The town is essentially one street running between the beach and the hills, with the bay on one side and El Choco National Park behind it.',
    'cabarete.faq.q2': 'How much does a transfer from POP airport to Cabarete cost?',
    'cabarete.faq.a2': 'US$33.95 one way, per vehicle, for 1 to 6 guests. Each passenger above six adds US$5. That price is fixed and confirmed in writing before you travel — there is no surge, no night rate and no luggage surcharge.',
    'cabarete.faq.q3': 'Which airport is closest to Cabarete?',
    'cabarete.faq.a3': 'Gregorio Luperón International Airport (POP) in Puerto Plata — it is on the same coast road and it is the one nearly every visitor uses. Santiago (Cibao, STI) is the next option, inland over the mountains. Everything else means crossing the country.',
    'cabarete.faq.q4': 'Can I reach Cabarete from Santo Domingo or Punta Cana?',
    'cabarete.faq.a4': 'Yes, and we do it regularly — but know what you are booking: both are on the other side of the country from Cabarete and mean several hours on the road. We quote them on request rather than publishing a figure, because we only publish prices we have confirmed. Ask on WhatsApp and you get a fixed number, and an honest journey time, back the same day.',
    'cabarete.faq.q5': 'How do I get from Amber Cove or Taino Bay to Cabarete?',
    'cabarete.faq.a5': "Both are private shore transfers. Taino Bay is inside Puerto Plata city and Amber Cove is in Maimón, just west of it, so either way the drive follows the coast east through Sosúa. We meet you outside the terminal gate and plan the day backwards from your ship's all-aboard time, so you return with a margin rather than a sprint.",
    'cabarete.faq.q6': 'Is there Uber in Cabarete?',
    'cabarete.faq.a6': 'No. There is no Uber or Lyft service in Cabarete, and none on this stretch of the north coast. Your realistic options are a pre-booked private transfer, a local taxi negotiated on the spot, or a motoconcho for short hops inside town.',
    'cabarete.faq.q7': 'What is the difference between Cabarete and Sosúa?',
    'cabarete.faq.a7': 'They are neighbours on the same coast road and they feel nothing alike. Cabarete is open water, wind and board sports, with the nightlife spilling onto the sand. Sosúa is a sheltered horseshoe bay with calm, clear water — better for snorkelling, families and anyone who wants to swim rather than be blown across a bay. Plenty of guests stay in one and spend evenings in the other; we run that hop constantly.',
    'cabarete.faq.q8': 'Do I have to pay in advance for a transfer to Cabarete?',
    'cabarete.faq.a8': 'No. Nothing is paid up front and no card details are taken. You pay your driver in cash on arrival, in US dollars or Dominican pesos. The reservation is confirmed by message, not by payment.',
    'cabarete.faq.q9': 'Can you carry kiteboards, surfboards and windsurf gear?',
    'cabarete.faq.a9': 'Yes, and at no surcharge — but tell us the count when you book, not at the kerb. Board bags decide which vehicle we send: a windsurf quiver needs a van, not a car. Give us the number of bags and their length in the same message as your flight number and the right vehicle turns up.',
    'cabarete.faq.q10': 'Do you drive late at night or very early in the morning?',
    'cabarete.faq.a10': 'Yes — we operate 24 hours a day, every day of the year. Cabarete flights land and leave at awkward hours and a pre-dawn departure to POP is an ordinary morning for us. Send the flight time and a driver will be outside.',
    'cabarete.book.heading': "Landing in Puerto Plata?<br /><em>Let's get you to Cabarete.</em>",
    'cabarete.book.lead': 'Send us your flight number, your arrival date and how many boards are coming with you. You get a fixed price back in writing, and a driver waiting at arrivals with your name on a sign.',
    'cabarete.air.onRequest': 'On request',
