    'meta.privacy.title': 'Privacy Policy | SG Caribbean Transfers & Tours',
    'meta.privacy.description': 'What SG Caribbean Transfers & Tours collects when you request a transfer or tour, how Google cookies are used, and how to change your choice.',
    'privacy.title': 'Privacy policy',
    'privacy.lead': 'What we collect when you use this site, why we collect it, and how to change your mind.',
    'privacy.updated': 'Last updated: November 1, 2026',
    'privacy.whoHeading': 'Who we are',
    'privacy.whoBody': 'SG Caribbean Transfers &amp; Tours is a private transfer and tour company based in Puerto Plata, Dominican Republic. For anything about your data, write to <a href="mailto:sg.caribbeantransferstours@gmail.com">sg.caribbeantransferstours@gmail.com</a> or message us on WhatsApp at +1 829-627-7733.',
    'privacy.collectHeading': 'What we collect',
    'privacy.collectIntro': 'You can browse this site without giving us your name. We only receive personal details when you send us a request.',
    'privacy.collectWhatsapp': '<strong>WhatsApp requests.</strong> Your message opens in WhatsApp with your trip details filled in, and we receive what you choose to send. WhatsApp handles that conversation under its own privacy policy.',
    'privacy.collectEmail': '<strong>Email requests.</strong> Our forms send your name, email address, trip details and message to us through Formspree, and we receive them in our Gmail inbox.',
    'privacy.collectTrip': '<strong>Trip details.</strong> Depending on what you book, these can include your route, dates, flight number, passengers, luggage and cruise ship.',
    'privacy.collectCart': '<strong>Your cart.</strong> It stays in your browser until you send or clear it. We do not see it before then.',
    'privacy.collectPayment': 'We do not take payments on this site. You pay the driver on arrival.',
    'privacy.useHeading': 'How we use it',
    'privacy.useBody': 'We use your details to answer you, confirm your booking and carry out your transfer or tour. We do not sell your details, and we do not use them for marketing unless you ask us to.',
    'privacy.cookiesHeading': 'Cookies and measurement',
    'privacy.cookiesBody': 'Google Analytics counts visits and pages viewed, and Google Ads tells us which ads led to a booking request. Google receives technical data such as your IP address, device, browser and the ad you clicked. We never send Google your name, email address or messages, and we do not use these tools for remarketing or personalized ads.',
    'privacy.cookiesChoice': 'Visitors in the European Economic Area, the United Kingdom, Switzerland and Quebec start with these cookies off until they accept. Everywhere else they start on, and you can reject them at any time. If you reject them, we delete the ones already set. Google may still receive a basic signal, with no cookies, that a page loaded or a request was sent.',
    'privacy.tableCaption': 'Cookies and browser storage on this site',
    'privacy.thName': 'Name',
    'privacy.thSetBy': 'Set by',
    'privacy.thPurpose': 'Purpose',
    'privacy.thLasts': 'Lasts',
    'privacy.thisSite': 'This site',
    'privacy.gaPurpose': 'Counts visits and pages viewed',
    'privacy.gaLasts': 'Up to 2 years',
    'privacy.adsPurpose': 'Links a booking request to the ad that brought you',
    'privacy.adsLasts': 'Up to 90 days',
    'privacy.cartPurpose': 'Keeps your cart',
    'privacy.cartLasts': 'Until you send or clear it',
    'privacy.consentPurpose': 'Remembers your cookie choice',
    'privacy.consentLasts': 'Until you change it or clear your browser data',
    'privacy.pickerPurpose': 'Remembers the service you picked on the home page',
    'privacy.pickerLasts': 'Until you close the tab',
    'privacy.providersHeading': 'Other companies involved',
    'privacy.providersIntro': 'These companies handle data when you use this site. Most are based in the United States, so your data may be processed outside your country.',
    'privacy.providerGithub': '<strong>GitHub Pages</strong> hosts this site and may log IP addresses to keep it running.',
    'privacy.providerFonts': '<strong>Google Fonts</strong> delivers the typefaces, so your browser connects to Google and shares your IP address.',
    'privacy.providerFormspree': '<strong>Formspree</strong> delivers our email forms to us.',
    'privacy.providerGoogle': '<strong>Google and WhatsApp</strong> handle the email, messages and measurement described above.',
    'privacy.keepHeading': 'How long we keep it',
    'privacy.keepBody': 'We keep booking messages for as long as we need them to handle your trip, answer follow-up questions and meet our legal and accounting duties.',
    'privacy.rightsHeading': 'Your choices and rights',
    'privacy.rightsBody': 'You can ask us what we hold about you, and ask us to correct or delete it, by writing to the address above. You can change your cookie choice at any time. Depending on where you live, you may also have the right to object to how we use your data, to receive a copy of it, and to complain to your data protection authority.',
    'privacy.changesHeading': 'Changes to this policy',
    'privacy.changesBody': 'If we change how we handle your data, we will update this page and the date at the top.',

