    'exc1.eyebrow': '01 — Bote y playa',
    'exc1.title': 'Punta Rusia',
    'exc1.desc': 'Descubre aguas cristalinas y un banco de arena privado en medio del mar — un paseo en bote a Cayo Arena, una de las aventuras más únicas de la costa norte. Grupos de 7 o más obtienen una mejor tarifa por persona — solo pregúntanos por WhatsApp.',
    'exc1.include1': 'Transporte terrestre y marítimo',
    'exc1.include2': 'Paseo en bote a Cayo Arena',
    'exc1.include3': 'Buffet dominicano',
    'exc1.include4': 'Agua, refresco y cerveza incluidos',
    'exc1.duration': 'Día completo · 8:00 a.m. – 5:30 p.m.',

    'exc2.eyebrow': '02 — Aventura',
    'exc2.title': 'Charcos de Damajagua',
    'exc2.desc': 'Escala, desliza y salta a través de cascadas naturales talladas en la selva — la aventura más emocionante de la costa norte.',
    'exc2.include1': 'Transporte ida y vuelta',
    'exc2.include2': 'Entrada al parque y equipo de seguridad',
    'exc2.include3': 'Guías certificados de canyoning',
    'exc2.include4': 'Almuerzo después de las cascadas',
    'exc2.include5': 'Nevera con agua, refresco y cerveza',
    'exc2.duration': 'Medio día · 8:30 a.m. – 2:00 p.m.',

    'exc4.eyebrow': '03 — Cultura',
    'exc4.title': 'Tour por la Ciudad de Puerto Plata',
    'exc4.desc': 'Casas victorianas, la fortaleza más antigua de América, vistas desde el teleférico del Monte Isabel de Torres y degustaciones de ámbar, ron y cacao. US$65 por persona, hasta 6 personas.',
    'exc4.include1': 'Transporte privado',
    'exc4.include2': 'Boletos de teleférico',
    'exc4.include3': 'Fortaleza San Felipe',
    'exc4.include4': 'Degustación de ron y chocolate',
    'exc4.include5': 'Nevera con agua, refresco y cerveza',
    'exc4.duration': 'Medio día · 9:00 a.m. – 2:30 p.m.',

    'exc5.eyebrow': '04 — Día relajado',
    'exc5.title': 'Experiencias de Playa',
    'exc5.desc': 'Playa Grande, Playa Encuentro, calas escondidas que solo los locales conocen — diseñamos tu día perfecto recorriendo playas.',
    'exc5.include1': 'Transporte privado todo el día',
    'exc5.include2': 'Sillas de playa y nevera con agua, refresco y cerveza',
    'exc5.include3': 'Guía local de playas',
    'exc5.include4': 'Parada para almuerzo de mariscos frescos',
    'exc5.duration': 'Flexible · Tú marcas el ritmo',

    'exc6.eyebrow': '05 — Aventura',
    'exc6.title': 'Aventura en ATV',
    'exc6.desc': 'Recorre senderos, ríos y campos al mando de tu propio ATV — una aventura llena de adrenalina por el interior dominicano.',
    'exc6.include1': 'Un ATV por participante',
    'exc6.include2': 'Equipo de seguridad y charla informativa',
