    'exc7.eyebrow': '06 — Aventura',
    'exc7.title': 'Aventura en Buggy',
    'exc7.desc': 'Toma el volante de tu propio buggy y explora senderos, ríos y caminos rurales — una experiencia emocionante para todo el grupo.',
    'exc7.include1': 'Un buggy por grupo',
    'exc7.include2': 'Equipo de seguridad y charla informativa',
    'exc7.include3': 'Guía experimentado',
    'exc7.include4': 'Transporte ida y vuelta',
    'exc7.include5': 'Nevera con agua y refresco',
