    'cruise.guaranteeTitle': 'De vuelta antes de zarpar — garantizado',
    'cruise.guaranteeBody': 'Controlamos la hora de zarpe de tu barco y diseñamos cada tour en torno a ella. Siempre regresas al puerto con tiempo de sobra.',
    'cruise.shipLabel': 'Barco de crucero (opcional)',
    'cruise.shipPlaceholder': 'ej. Carnival Vista',
    'cruise.departureLabel': 'Hora de zarpe (opcional)',
    'cruise.departsAt': 'zarpa',

    'cruise1.title': 'Charcos de Damajagua',
    'cruise1.desc': 'Pozas de piedra caliza que subes para luego bajarlas saltando y deslizándote. A cerca de una hora de cualquiera de los dos muelles, así que entra cómodo en una escala normal. Trae traje de baño y zapatos que no te importe mojar.',
    'cruise1.duration': 'Medio día',
    'cruise2.title': 'Tour por la Ciudad de Puerto Plata',
    'cruise2.desc': 'El trayecto más corto desde cualquiera de los dos muelles — Taino Bay está dentro de la propia ciudad. Fortaleza San Felipe, casco antiguo victoriano, teleférico al Pico Isabel de Torres y degustaciones de ámbar, ron y cacao. La opción cuando tu barco hace escala corta. US$65 por persona, hasta 6 personas.',
    'cruise2.duration': 'Medio día',
    'cruise4.title': 'Aventura en ATV',
    'cruise4.desc': 'Tu propio ATV por senderos de campo, cruces de río y caminos detrás de Puerto Plata. A media hora aproximada de Amber Cove o Taino Bay — polvoriento, ruidoso, y resuelto en medio día con la tarde todavía libre.',
    'cruise4.duration': 'Medio día',
    'cruise5.title': 'Aventura en Buggy',
    'cruise5.desc': 'El mismo interior que los ATV, pero lado a lado y bajo barra antivuelco — más fácil si prefieres turnarte al volante. A media hora aproximada de cualquiera de los dos muelles, y planificado hacia atrás desde tu hora de embarque.',
    'cruise5.duration': 'Medio día',

