    'why.eyebrow': '¿Por qué elegirnos?',
    'why.heading': '¿Qué nos diferencia?',
    'why.lead': 'En SG Caribbean Transfers &amp; Tours creemos que un tour es mucho más que transportar personas de un lugar a otro. Nuestra misión es hacer que cada visitante viva una experiencia segura, cómoda y auténtica desde el primer contacto hasta el final de su aventura.',
    'why.card1Title': 'Servicio Seguro y Confiable',
    'why.card1Desc': 'Tu seguridad y tranquilidad son nuestra prioridad durante todo el recorrido.',
    'why.card2Title': 'Conocimiento Local',
    'why.card2Desc': 'Conocemos a la perfección Sosúa, Cabarete, Puerto Plata y los principales destinos turísticos de la región, por lo que podemos recomendar los mejores lugares y experiencias.',
    'why.card3Title': 'Puntualidad Garantizada',
    'why.card3Desc': 'Sabemos que el tiempo de tus vacaciones es valioso. Siempre llegamos a tiempo para que disfrutes al máximo.',
    'why.card4Title': 'Atención Personalizada',
    'why.card4Desc': 'Tratamos a cada cliente como un invitado, no como un número. Nos adaptamos a sus necesidades y horarios.',
    'why.card5Title': 'Comunicación Clara y Amable',
    'why.card5Desc': 'Estamos disponibles para responder preguntas antes, durante y después de cada tour, brindando un servicio cercano y profesional.',
    'why.card6Title': 'Experiencias Inolvidables',
    'why.card6Desc': 'No solo ofrecemos excursiones y traslados; creamos recuerdos que harán que quieras volver a la República Dominicana.',
    'why.stat1': 'Años en la carretera',
    'why.stat2': 'Viajeros felices',
    'why.stat3': 'Calificación promedio',
    'why.stat4': 'Recogidas perdidas',

    'about.introEyebrow': 'Quiénes somos',
    'about.introHeading': 'Un negocio familiar en <em>la costa norte</em>',
    'about.introBody': 'SG Caribbean Transfers & Tours nació en la costa norte de República Dominicana, a partir de una idea simple: todo visitante merece un traslado seguro, cómodo y un chofer que lo trate como familia. Hoy nuestro equipo transporta a miles de viajeros al año entre los aeropuertos, Sosúa, Cabarete y Puerto Plata — siempre puntuales, siempre privados.',

    'about.eyebrow': 'Conoce al equipo',
    'about.heading': 'Las personas detrás <em>del volante</em>',
    'about.lead': 'Saul, Sariel, Luis y Leuris — cuatro choferes locales que conocen cada carretera de la costa norte y tratan a cada huésped como familia.',
    'about.role': 'Chofer profesional',
    'about.fleetHeading': 'Viaja en Toyota Hiace, siempre <em>impecable</em>',
    'about.fleet1': 'La flota Hiace — espacio hasta para 15 huéspedes',
    'about.fleet2': 'Lavada e inspeccionada antes de cada recogida',
    'about.fleet3': 'Interiores impecables con aire acondicionado',
    'about.fleet4': 'Cada van, lista para la carretera',
    'about.fleet5': 'Personalizadas y probadas en carretera',
    'about.fleet6': 'La incorporación más nueva a la flota',
    'about.fleet7': 'Asientos cómodos para cualquier tamaño de grupo',
    'about.fleet8': 'Amplias e impecables en cada viaje',

    'reviews.eyebrow': 'Opiniones de huéspedes',
    'reviews.heading': 'La confianza de viajeros <em>de todo el mundo</em>',
    'reviews.starsAria': '5 de 5 estrellas',
    'reviews.quote1': '"Nuestro chofer nos esperaba con un cartel aunque nuestro vuelo llegó 2 horas tarde. Agua fría, van impecable, cero estrés. Así debería empezar toda vacación."',
    'reviews.quote2': '"El tour de Experiencias de Playa fue lo más destacado de nuestra luna de miel. Solo nosotros dos, calas escondidas, y el agua más clara que he visto. Vale cada dólar."',
    'reviews.quote3': '"Viajamos con 9 familiares y dos sillas para niños. Todo se organizó por WhatsApp en minutos. Precio fijo justo, van hermosa, chofer amable."',
    'reviews.quote4': '"27 Charcos con Sariel fue pura adrenalina — los guías nos hicieron sentir seguros todo el camino. Luego pescado fresco en la playa. Día perfecto."',
    'reviews.readOnGoogle': 'Lee nuestras reseñas en Google',
    'reviews.readOnGoogleCount': 'Lee las {count} reseñas en Google',

    'faq.eyebrow': 'Información útil',
    'faq.heading': 'Preguntas <em>respondidas</em>',
    'faq.q1': '¿Ofrecen sillas para niños?',
    'faq.a1': 'Sí — las sillas para bebés y elevadores están disponibles sin costo. Solo dinos la edad de tus pequeños al reservar y tendremos la silla correcta instalada antes de la recogida.',
    'faq.q2': '¿Puedo pagar al llegar?',
    'faq.a2': 'Sí. No se requiere pago anticipado para confirmar tu reserva — le pagas a tu chofer en efectivo (USD o pesos dominicanos) al encontrarnos. Pago con tarjeta disponible a solicitud.',
    'faq.q3': '¿Cuántos pasajeros caben en el vehículo?',
    'faq.a3': 'Los autos privados llevan hasta 3 pasajeros, las minivans hasta 6, las vans hasta 10 y los minibuses hasta 15 — todos con espacio para equipaje estándar. ¿Viajas con tablas de surf o maletas extra? Dínoslo y lo planificamos.',
    'faq.q4': '¿Qué pasa si mi vuelo se retrasa?',
    'faq.a4': 'Para ti nada cambia. Monitoreamos tu número de vuelo en tiempo real y ajustamos la recogida automáticamente — tu chofer estará esperando cuando aterrices, sin costo adicional.',
    'faq.q5': '¿Las excursiones son privadas?',
    'faq.a5': 'Totalmente. Cada excursión es solo para tu grupo — tu propio vehículo, tu propio guía, tu propio horario. Sin desconocidos, sin esperar a que se llene un autobús.',
    'faq.q6': '¿Trabajan de noche y los fines de semana?',
    'faq.a6': 'Sí — trabajamos 24 horas al día, todos los días del año. Salidas de madrugada, aterrizajes de noche, domingos y feriados son normales para nosotros: dinos la hora de tu vuelo y ahí estará un chofer.',

    /* --- sosua.html: página de destino (SEO / motores de respuesta) ---
       Los precios reflejan js/config.js y transfers.html; distancias y
       tiempos son aproximados por carretera. */
    'sosua.hero.eyebrow': 'Sosúa · Puerto Plata · República Dominicana',
    'sosua.hero.title': 'Llegar a Sosúa, <em>resuelto antes de aterrizar</em>',
    'sosua.hero.lead': 'El aeropuerto de Puerto Plata está a 15 minutos. Los muelles de cruceros, a 50. Llegues como llegues, un chofer local ya te espera — con el precio acordado antes de salir de casa.',

    'sosua.answer.eyebrow': 'La versión corta',
    'sosua.answer.heading': 'Cómo llegar a Sosúa, <em>en 30 segundos</em>',
    'sosua.answer.lead': 'Sosúa es un pueblo de playa en la costa norte de la República Dominicana, en la provincia de Puerto Plata. El aeropuerto más cercano es el Gregorio Luperón (POP), a unos 9 km — cerca de 15 minutos en carro. SG Caribbean Transfers &amp; Tours hace transfers privados puerta a puerta desde POP hasta Sosúa por un precio fijo de US$23.95 para 1 a 6 pasajeros, sin pago por adelantado: le pagas a tu chofer en efectivo al llegar.',
    'sosua.answer.f1Label': 'Aeropuerto más cercano',
    'sosua.answer.f1Value': 'Puerto Plata (POP) — 9 km, ~15 min',
    'sosua.answer.f2Label': 'Precio fijo del transfer',
    'sosua.answer.f2Value': 'US$23.95 por trayecto, 1–6 pasajeros',
    'sosua.answer.f3Label': 'Muelles de crucero más cercanos',
    'sosua.answer.f3Value': 'Taino Bay ~50 min · Amber Cove ~60 min',
