    'sosua.air.pujTime': '~4 h 45',
    'sosua.air.note': 'Suma US$5 por cada pasajero por encima de seis. Las distancias y los tiempos son aproximados y dependen del tráfico y de tu dirección exacta en Sosúa. Los precios son por vehículo, no por persona.',
    'sosua.air.stepsHeading': 'Qué pasa el día que aterrizas',
    'sosua.air.step1Title': 'Nos envías el número de vuelo',
    'sosua.air.step1Body': 'Con un mensaje de WhatsApp basta — sin cuenta, sin formulario, sin datos de tarjeta. Te respondemos con el precio confirmado por escrito.',
    'sosua.air.step2Title': 'Miramos el vuelo, no el reloj',
    'sosua.air.step2Body': 'Si aterrizas dos horas tarde, la recogida se mueve dos horas. Tu chofer espera sin costo adicional — los retrasos son problema nuestro, no tuyo.',
    'sosua.air.step3Title': 'Cartel con tu nombre en llegadas, y directo a tu puerta',
    'sosua.air.step3Body': 'Tu chofer te recibe adentro con un cartel, te ayuda con las maletas y te lleva a tu hotel, villa o Airbnb en Sosúa. Pide una parada en el supermercado o el cajero y no cuesta nada extra.',
    'sosua.air.cta': 'Ver todos los precios de transfer',
    'sosua.air.ctaAlt': 'Cotizar otro destino',

    'sosua.cruise.eyebrow': 'Si llegas en crucero',
    'sosua.cruise.heading': 'Sosúa es <em>medio día tranquilo</em> desde cualquiera de los dos muelles',
    'sosua.cruise.lead': 'Las dos terminales de crucero de Puerto Plata están a cerca de una hora de Sosúa, así que la playa es una excursión independiente cómoda — no una carrera contra el reloj.',
    'sosua.cruise.tainoTitle': 'Taino Bay → Sosúa',
    'sosua.cruise.tainoMeta': '~27 km · ~50 min',
    'sosua.cruise.tainoBody': 'Taino Bay está dentro de la ciudad de Puerto Plata, así que estarás en la carretera costera pocos minutos después de bajar del barco. Te esperamos a la salida de la terminal.',
    'sosua.cruise.amberTitle': 'Amber Cove → Sosúa',
    'sosua.cruise.amberMeta': '~32 km · ~60 min',
    'sosua.cruise.amberBody': 'Amber Cove está en Maimón, justo al oeste de Puerto Plata. El camino a Sosúa sigue la misma carretera de la costa, pasando por Playa Dorada y el desvío del aeropuerto.',
    'sosua.cruise.timingTitle': 'La cuenta del all-aboard, hecha por nosotros',
    'sosua.cruise.timingBody': 'Una escala típica en Puerto Plata dura de 8 a 9 horas. La ida y vuelta a Sosúa consume aproximadamente 2 horas de manejo, lo que aún te deja seis horas o más en tierra. Planificamos cada día de crucero hacia atrás desde la hora de embarque de tu barco y te devolvemos al muelle con margen, nunca justo a tiempo.',
    'sosua.cruise.cta': 'Ver excursiones para cruceros',
    'sosua.cruise.ctaAlt': 'Pedir cotización para día de crucero',

