    'puertoplata.air.step2Body': 'Si aterrizas dos horas tarde, la recogida se mueve dos horas. Tu chofer espera sin costo extra — los retrasos son problema nuestro, no tuyo.',
    'puertoplata.air.step3Title': 'Cartel con tu nombre a la salida, y directo a tu puerta',
