    'consent.title': 'Cookies en este sitio',
    'consent.text': 'Usamos cookies de Google para contar visitas y saber qué anuncios traen solicitudes de reserva. Nunca le damos a Google tu nombre, tu correo ni tus mensajes.',
    'consent.policyLink': 'Lee nuestra política de privacidad',
