    'meta.privacy.title': 'Política de privacidad | SG Caribbean Transfers & Tours',
    'meta.privacy.description': 'Qué datos recoge SG Caribbean Transfers & Tours cuando pides un transfer o una excursión, cómo se usan las cookies de Google y cómo cambiar tu elección.',
    'privacy.title': 'Política de privacidad',
    'privacy.lead': 'Qué recogemos cuando usas este sitio, para qué lo recogemos y cómo cambiar de opinión.',
    'privacy.updated': 'Última actualización: 1 de noviembre de 2026',
    'privacy.whoHeading': 'Quiénes somos',
    'privacy.whoBody': 'SG Caribbean Transfers &amp; Tours es una empresa de transfers privados y excursiones con sede en Puerto Plata, República Dominicana. Para cualquier tema sobre tus datos, escribe a <a href="mailto:sg.caribbeantransferstours@gmail.com">sg.caribbeantransferstours@gmail.com</a> o por WhatsApp al +1 829-627-7733.',
    'privacy.collectHeading': 'Qué recogemos',
    'privacy.collectIntro': 'Puedes navegar por este sitio sin darnos tu nombre. Solo recibimos datos personales cuando nos envías una solicitud.',
    'privacy.collectWhatsapp': '<strong>Solicitudes por WhatsApp.</strong> Tu mensaje se abre en WhatsApp con los datos del viaje ya escritos, y recibimos lo que decidas enviar. WhatsApp gestiona esa conversación según su propia política de privacidad.',
    'privacy.collectEmail': '<strong>Solicitudes por correo.</strong> Nuestros formularios nos envían tu nombre, correo, datos del viaje y mensaje a través de Formspree, y los recibimos en nuestra bandeja de Gmail.',
    'privacy.collectTrip': '<strong>Datos del viaje.</strong> Según lo que reserves, pueden incluir tu ruta, fechas, número de vuelo, pasajeros, equipaje y crucero.',
    'privacy.collectCart': '<strong>Tu carrito.</strong> Se queda en tu navegador hasta que lo envíes o lo vacíes. No lo vemos antes de eso.',
    'privacy.collectPayment': 'No cobramos pagos en este sitio. Le pagas al conductor al llegar.',
    'privacy.useHeading': 'Cómo lo usamos',
    'privacy.useBody': 'Usamos tus datos para responderte, confirmar tu reserva y realizar tu transfer o excursión. No vendemos tus datos ni los usamos para marketing, salvo que nos lo pidas.',
    'privacy.cookiesHeading': 'Cookies y medición',
    'privacy.cookiesBody': 'Google Analytics cuenta las visitas y las páginas vistas, y Google Ads nos indica qué anuncios llevaron a una solicitud de reserva. Google recibe datos técnicos como tu dirección IP, dispositivo, navegador y el anuncio en el que hiciste clic. Nunca le enviamos a Google tu nombre, tu correo ni tus mensajes, y no usamos estas herramientas para remarketing ni anuncios personalizados.',
    'privacy.cookiesChoice': 'Para quienes visitan desde el Espacio Económico Europeo, el Reino Unido, Suiza y Quebec, estas cookies están apagadas hasta que las acepten. En el resto del mundo están activas, y puedes rechazarlas cuando quieras. Si las rechazas, borramos las que ya estén guardadas. Google aún puede recibir una señal básica, sin cookies, de que se cargó una página o se envió una solicitud.',
    'privacy.tableCaption': 'Cookies y almacenamiento del navegador en este sitio',
    'privacy.thName': 'Nombre',
    'privacy.thSetBy': 'Origen',
    'privacy.thPurpose': 'Para qué sirve',
    'privacy.thLasts': 'Duración',
    'privacy.thisSite': 'Este sitio',
    'privacy.gaPurpose': 'Cuenta las visitas y las páginas vistas',
    'privacy.gaLasts': 'Hasta 2 años',
    'privacy.adsPurpose': 'Relaciona una solicitud de reserva con el anuncio que te trajo',
    'privacy.adsLasts': 'Hasta 90 días',
