    'privacy.pickerPurpose': 'Recuerda el servicio que elegiste en la página de inicio',
    'privacy.pickerLasts': 'Hasta que cierres la pestaña',
    'privacy.providersHeading': 'Otras empresas que intervienen',
    'privacy.providersIntro': 'Estas empresas manejan datos cuando usas este sitio. La mayoría tiene sede en Estados Unidos, así que tus datos pueden tratarse fuera de tu país.',
    'privacy.providerGithub': '<strong>GitHub Pages</strong> aloja este sitio y puede registrar direcciones IP para mantenerlo en funcionamiento.',
    'privacy.providerFonts': '<strong>Google Fonts</strong> entrega las tipografías, así que tu navegador se conecta a Google y comparte tu dirección IP.',
    'privacy.providerFormspree': '<strong>Formspree</strong> nos entrega los formularios de correo.',
    'privacy.providerGoogle': '<strong>Google y WhatsApp</strong> gestionan el correo, los mensajes y la medición descritos arriba.',
    'privacy.keepHeading': 'Cuánto tiempo lo guardamos',
    'privacy.keepBody': 'Guardamos los mensajes de reserva el tiempo necesario para gestionar tu viaje, responder preguntas posteriores y cumplir nuestras obligaciones legales y contables.',
    'privacy.rightsHeading': 'Tus opciones y derechos',
    'privacy.rightsBody': 'Puedes preguntarnos qué datos tenemos sobre ti y pedirnos que los corrijamos o los borremos, escribiendo a la dirección de arriba. Puedes cambiar tu elección sobre cookies cuando quieras. Según dónde vivas, también puedes tener derecho a oponerte a cómo usamos tus datos, a recibir una copia y a reclamar ante tu autoridad de protección de datos.',
    'privacy.changesHeading': 'Cambios en esta política',
    'privacy.changesBody': 'Si cambiamos la forma de manejar tus datos, actualizaremos esta página y la fecha de arriba.',

