    'cruise.guaranteeTitle': "De retour avant l'appareillage — garanti",
    'cruise.guaranteeBody': "Nous suivons l'heure de départ de votre bateau et organisons chaque excursion en conséquence. Vous êtes toujours de retour au port avec du temps devant vous.",
    'cruise.shipLabel': 'Bateau de croisière (facultatif)',
    'cruise.shipPlaceholder': 'ex. Carnival Vista',
    'cruise.departureLabel': 'Heure de départ (facultatif)',
