    'cruise1.title': 'Charcos de Damajagua',
    'cruise1.desc': "Des vasques calcaires que l'on remonte avant de les redescendre en sautant et en glissant. À environ une heure de l'un ou l'autre quai, ce qui tient confortablement dans une escale normale. Prévoyez maillot et chaussures que vous pouvez mouiller.",
    'cruise1.duration': 'Demi-journée',
    'cruise2.title': 'Visite de la Ville de Puerto Plata',
    'cruise2.desc': "Le trajet le plus court depuis les deux quais — Taino Bay se trouve dans la ville même. Forteresse San Felipe, vieille ville victorienne, téléphérique du Pico Isabel de Torres, et dégustations d'ambre, de rhum et de cacao. Le choix quand votre navire fait une escale courte. 65 $US par personne, jusqu'à 6 personnes.",
    'cruise2.duration': 'Demi-journée',
    'cruise4.title': 'Aventure en Quad',
    'cruise4.desc': "Votre propre quad sur les sentiers de campagne, les gués et les chemins derrière Puerto Plata. À environ une demi-heure d'Amber Cove ou de Taino Bay — poussiéreux, bruyant, bouclé en une demi-journée avec l'après-midi encore devant vous.",
    'cruise4.duration': 'Demi-journée',
    'cruise5.title': 'Aventure en Buggy',
    'cruise5.desc': "Le même arrière-pays que les quads, mais côte à côte sous un arceau de sécurité — plus simple si vous préférez vous relayer au volant. À environ une demi-heure de l'un ou l'autre quai, et calé à rebours de votre heure d'embarquement.",
    'cruise5.duration': 'Demi-journée',

