    'why.eyebrow': 'Pourquoi nous choisir ?',
    'why.heading': 'Ce qui nous distingue',
    'why.lead': "Chez SG Caribbean Transfers &amp; Tours, nous pensons qu'une excursion est bien plus que le simple fait de déplacer des personnes d'un endroit à un autre. Notre mission est de faire vivre à chaque visiteur une expérience sûre, confortable et authentique, du premier contact jusqu'à la fin de son aventure.",
    'why.card1Title': 'Service Sûr et Fiable',
    'why.card1Desc': "Votre sécurité et votre tranquillité d'esprit sont notre priorité tout au long du trajet.",
    'why.card2Title': 'Connaissance Locale',
    'why.card2Desc': 'Nous connaissons parfaitement Sosúa, Cabarete, Puerto Plata et les meilleures destinations de la région, afin de pouvoir vous recommander les meilleurs endroits et expériences.',
    'why.card3Title': 'Ponctualité Garantie',
    'why.card3Desc': "Nous savons que le temps de vos vacances est précieux. Nous arrivons toujours à l'heure pour que vous en profitiez au maximum.",
    'why.card4Title': 'Attention Personnalisée',
    'why.card4Desc': 'Nous traitons chaque client comme un invité, pas comme un numéro. Nous nous adaptons à vos besoins et à votre horaire.',
    'why.card5Title': 'Communication Claire et Amicale',
    'why.card5Desc': 'Nous sommes disponibles pour répondre à vos questions avant, pendant et après chaque excursion, avec un service proche et professionnel.',
    'why.card6Title': 'Expériences Inoubliables',
    'why.card6Desc': "Nous n'offrons pas seulement des excursions et des transferts ; nous créons des souvenirs qui vous donneront envie de revenir en République Dominicaine.",
    'why.stat1': 'Années sur la route',
    'why.stat2': 'Voyageurs satisfaits',
    'why.stat3': 'Note moyenne',
    'why.stat4': 'Prises en charge manquées',

    'about.introEyebrow': 'Qui sommes-nous',
    'about.introHeading': 'Une entreprise familiale sur <em>la côte nord</em>',
    'about.introBody': "SG Caribbean Transfers & Tours est né sur la côte nord de la République Dominicaine, à partir d'une idée simple : chaque visiteur mérite un trajet sûr, confortable et un chauffeur qui le traite comme un membre de la famille. Aujourd'hui, notre équipe transporte des milliers de voyageurs chaque année entre les aéroports, Sosúa, Cabarete et Puerto Plata — toujours à l'heure, toujours en privé.",

    'about.eyebrow': "Rencontrez l'équipe",
    'about.heading': 'Les personnes derrière <em>le volant</em>',
    'about.lead': 'Saul, Sariel, Luis et Leuris — quatre chauffeurs locaux qui connaissent chaque route de la côte nord et traitent chaque client comme un membre de la famille.',
    'about.role': 'Chauffeur professionnel',
    'about.fleetHeading': 'Voyagez en Toyota Hiace, toujours <em>impeccable</em>',
    'about.fleet1': "La flotte Hiace — jusqu'à 15 personnes",
    'about.fleet2': 'Nettoyée et inspectée avant chaque prise en charge',
    'about.fleet3': 'Intérieurs climatisés et impeccables',
    'about.fleet4': 'Chaque fourgonnette, prête pour la route',
    'about.fleet5': 'Personnalisées et testées sur route',
    'about.fleet6': 'La toute dernière addition à notre flotte',
    'about.fleet7': 'Sièges confortables pour tous les groupes',
    'about.fleet8': 'Spacieuses et impeccables, à chaque trajet',

    'reviews.eyebrow': 'Avis de nos clients',
    'reviews.heading': 'La confiance de voyageurs <em>du monde entier</em>',
    'reviews.starsAria': '5 étoiles sur 5',
    'reviews.quote1': "« Notre chauffeur nous attendait avec une pancarte même si notre vol avait atterri avec 2 heures de retard. Eau fraîche, van impeccable, zéro stress. C'est ainsi que devraient commencer toutes les vacances. »",
    'reviews.quote2': "« L'excursion Expériences de Plage a été le point fort de notre lune de miel. Juste nous deux, des criques cachées, et l'eau la plus claire que j'aie jamais vue. Chaque dollar en valait la peine. »",
    'reviews.quote3': '« Nous avons voyagé avec 9 membres de la famille et deux sièges auto. Tout a été organisé sur WhatsApp en quelques minutes. Prix fixe honnête, belle van, chauffeur aimable. »',
    'reviews.quote4': "« Les 27 Charcos avec Sariel, c'était de l'adrénaline pure — les guides nous ont fait sentir en sécurité tout du long. Puis du poisson frais sur la plage. Journée parfaite. »",
    'reviews.readOnGoogle': 'Lire nos avis sur Google',
    'reviews.readOnGoogleCount': 'Lire les {count} avis sur Google',

    'faq.eyebrow': 'Bon à savoir',
    'faq.heading': 'Questions <em>répondues</em>',
    'faq.q1': 'Proposez-vous des sièges pour enfants ?',
    'faq.a1': "Oui — les sièges bébé et rehausseurs sont disponibles gratuitement. Indiquez-nous simplement l'âge de vos enfants lors de la réservation et nous installerons le bon siège avant la prise en charge.",
    'faq.q2': "Puis-je payer à l'arrivée ?",
    'faq.a2': "Oui. Aucun paiement anticipé n'est requis pour confirmer votre réservation — vous payez votre chauffeur en espèces (USD ou pesos dominicains) à notre rencontre. Le paiement par carte est disponible sur demande.",
    'faq.q3': 'Combien de passagers tiennent dans le véhicule ?',
    'faq.a3': "Les voitures privées accueillent jusqu'à 3 personnes, les minifourgonnettes jusqu'à 6, les fourgonnettes jusqu'à 10 et les minibus jusqu'à 15 — tous avec de l'espace pour les bagages standards. Vous voyagez avec des planches de surf ou des bagages supplémentaires ? Dites-le-nous et nous nous organiserons.",
    'faq.q4': 'Que se passe-t-il si mon vol est retardé ?',
    'faq.a4': 'Rien ne change pour vous. Nous surveillons votre numéro de vol en temps réel et ajustons automatiquement la prise en charge — votre chauffeur vous attendra à votre atterrissage, sans frais supplémentaires.',
    'faq.q5': 'Les excursions sont-elles privées ?',
    'faq.a5': "Complètement. Chaque excursion est réservée à votre groupe uniquement — votre propre véhicule, votre propre guide, votre propre horaire. Pas d'inconnus, pas d'attente pour qu'un bus se remplisse.",
    'faq.q6': 'Travaillez-vous la nuit et le week-end ?',
    'faq.a6': "Oui — nous roulons 24 heures sur 24, tous les jours de l'année. Départs à l'aube, atterrissages tardifs, dimanches et jours fériés sont normaux pour nous : donnez-nous l'heure de votre vol et un chauffeur sera là.",

    /* --- sosua.html : page de destination (SEO / moteurs de réponse) ---
       Les prix reflètent js/config.js et transfers.html ; distances et
       durées sont des estimations routières approximatives. */
    'sosua.hero.eyebrow': 'Sosúa · Puerto Plata · République Dominicaine',
    'sosua.hero.title': 'Rejoindre Sosúa, <em>réglé avant même d&#39;atterrir</em>',
    'sosua.hero.lead': "L'aéroport de Puerto Plata est à 15 minutes. Les quais de croisière, à 50. Quelle que soit votre arrivée, un chauffeur local vous attend déjà — au prix convenu avant votre départ.",

    'sosua.answer.eyebrow': 'En bref',
    'sosua.answer.heading': 'Comment aller à Sosúa, <em>en 30 secondes</em>',
    'sosua.answer.lead': "Sosúa est une ville balnéaire de la côte nord de la République Dominicaine, dans la province de Puerto Plata. L'aéroport le plus proche est le Gregorio Luperón International (POP), à environ 9 km — soit à peu près 15 minutes de route. SG Caribbean Transfers &amp; Tours assure des transferts privés porte-à-porte de POP à Sosúa au prix fixe de 23,95 $ US pour 1 à 6 passagers, sans acompte : vous payez votre chauffeur en espèces à l'arrivée.",
    'sosua.answer.f1Label': 'Aéroport le plus proche',
    'sosua.answer.f1Value': 'Puerto Plata (POP) — 9 km, ~15 min',
