    'sosua.air.pujTime': '~4 h 45',
    'sosua.air.note': 'Ajoutez 5 $ US par passager au-delà de six. Les distances et les durées sont approximatives et dépendent du trafic et de votre adresse exacte à Sosúa. Les prix sont par véhicule, pas par personne.',
    'sosua.air.stepsHeading': 'Ce qui se passe le jour de votre arrivée',
    'sosua.air.step1Title': 'Vous nous envoyez votre numéro de vol',
    'sosua.air.step1Body': 'Un seul message WhatsApp suffit — pas de compte, pas de formulaire, pas de carte bancaire. Nous répondons avec le prix confirmé par écrit.',
    'sosua.air.step2Title': 'Nous suivons le vol, pas la montre',
    'sosua.air.step2Body': "Si vous atterrissez avec deux heures de retard, la prise en charge est décalée d'autant. Votre chauffeur attend sans supplément — les retards sont notre problème, pas le vôtre.",
    'sosua.air.step3Title': 'Pancarte à votre nom aux arrivées, puis directement chez vous',
    'sosua.air.step3Body': "Votre chauffeur vous accueille à l'intérieur avec une pancarte, vous aide avec les bagages et vous conduit à votre hôtel, villa ou Airbnb à Sosúa. Demandez un arrêt supermarché ou distributeur en chemin : c'est sans supplément.",
    'sosua.air.cta': 'Voir tous les prix de transfert',
