    'sosua.cruise.eyebrow': 'Si vous arrivez en croisière',
    'sosua.cruise.heading': 'Sosúa, <em>une demi-journée tranquille</em> depuis les deux quais',
    'sosua.cruise.lead': "Les deux terminaux de croisière de Puerto Plata sont à environ une heure de Sosúa, ce qui fait de la plage une excursion indépendante confortable — pas une course contre la montre.",
    'sosua.cruise.tainoTitle': 'Taino Bay → Sosúa',
    'sosua.cruise.tainoMeta': '~27 km · ~50 min',
    'sosua.cruise.tainoBody': "Taino Bay se trouve en pleine ville de Puerto Plata : vous êtes sur la route côtière quelques minutes après avoir quitté le navire. Nous vous attendons à la sortie du terminal.",
    'sosua.cruise.amberTitle': 'Amber Cove → Sosúa',
    'sosua.cruise.amberMeta': '~32 km · ~60 min',
    'sosua.cruise.amberBody': "Amber Cove est à Maimón, juste à l'ouest de Puerto Plata. La route vers Sosúa suit le même axe côtier, en passant par Playa Dorada et la bretelle de l'aéroport.",
    'sosua.cruise.timingTitle': "Le calcul de l'heure d'embarquement, fait pour vous",
    'sosua.cruise.timingBody': "Une escale type à Puerto Plata dure 8 à 9 heures. Un aller-retour à Sosúa en consomme environ 2 heures de route, ce qui vous laisse encore six heures ou plus à terre. Nous construisons chaque journée de croisière à rebours de l'heure d'embarquement de votre navire et vous ramenons au quai avec de la marge, jamais à la dernière minute.",
    'sosua.cruise.cta': 'Voir les excursions pour croisiéristes',
    'sosua.cruise.ctaAlt': 'Demander un devis journée croisière',

    'sosua.compare.eyebrow': 'Pourquoi nous choisir',
