    'sosua.compare.lead': "Nous ne sommes pas la seule option et nous ne prétendons pas l'être. Voici ce qui change vraiment une fois que vous êtes dans le hall des arrivées avec vos valises.",
    'sosua.compare.caption': 'Le transfert privé comparé aux alternatives habituelles pour rejoindre Sosúa',
