    'sosua.compare.priceUs': 'Fixe et confirmé par écrit avant votre vol — 23,95 $ US depuis POP pour 1–6 passagers',
    'sosua.compare.priceTaxi': "Négocié sur le trottoir ; varie selon le chauffeur, l'heure et votre air fatigué",
    'sosua.compare.priceShuttle': 'Généralement facturé par personne, donc le total grimpe avec la taille du groupe',
    'sosua.compare.priceRental': 'Tarif journalier plus assurance, carburant et stationnement',
    'sosua.compare.rowLate': 'Si votre vol a du retard',
    'sosua.compare.lateUs': 'Nous suivons le numéro de vol et décalons la prise en charge ; votre chauffeur attend sans frais',
    'sosua.compare.lateTaxi': 'Vous commencez à chercher une voiture une fois dehors',
    'sosua.compare.lateShuttle': 'Les départs sont à horaires fixes ; un atterrissage tardif peut signifier la navette suivante',
    'sosua.compare.lateRental': 'Le comptoir de location peut déjà être fermé',
    'sosua.compare.rowWho': 'Qui voyage avec vous',
    'sosua.compare.whoUs': "Votre groupe uniquement, dans un Toyota Hiace privé climatisé jusqu'à 15 places",
    'sosua.compare.whoTaxi': 'Votre groupe uniquement, dans la voiture suivante de la file',
    'sosua.compare.whoShuttle': "D'autres passagers, et chaque dépose avant la vôtre",
    'sosua.compare.whoRental': 'Votre groupe uniquement — mais après un long vol, le conducteur, c’est vous',
    'sosua.compare.rowStops': 'Arrêts en chemin',
    'sosua.compare.stopsUs': 'Supermarché, distributeur ou pharmacie sur demande, sans supplément',
    'sosua.compare.stopsTaxi': 'Parfois, généralement moyennant un supplément',
