    'cabarete.compare.rowPrice': 'Prix',
    'cabarete.compare.priceUs': 'Fixe et confirmé par écrit avant le voyage',
    'cabarete.compare.priceTaxi': 'Négocié sur le trottoir, souvent plus cher la nuit',
    'cabarete.compare.priceShuttle': 'Bon marché par siège, mais généralement par personne',
    'cabarete.compare.priceRental': 'Tarif journalier plus assurance, carburant et stationnement',
    'cabarete.compare.rowLate': 'Si le vol a du retard',
    'cabarete.compare.lateUs': 'Nous suivons le numéro de vol et décalons la prise en charge — sans supplément',
    'cabarete.compare.lateTaxi': 'Celui qui reste sur la file à cette heure-là',
