    'cabarete.compare.whoRental': 'Vous, au volant',
    'cabarete.compare.rowStops': 'Planches et bagages volumineux',
    'cabarete.compare.stopsUs': 'Dites-nous combien et nous envoyons un van adapté — sans supplément',
    'cabarete.compare.stopsTaxi': 'Dépend entièrement de la voiture qui se présente',
    'cabarete.compare.stopsShuttle': 'Souvent refusées ou facturées comme siège supplémentaire',
