    'consent.title': 'Cookies sur ce site',
    'consent.text': 'Nous utilisons des cookies Google pour compter les visites et savoir quelles annonces génèrent des demandes de réservation. Nous ne transmettons jamais à Google votre nom, votre email ni vos messages.',
    'consent.policyLink': 'Lire notre politique de confidentialité',
