    'meta.privacy.title': 'Politique de confidentialité | SG Caribbean Transfers & Tours',
    'meta.privacy.description': 'Ce que SG Caribbean Transfers & Tours collecte lorsque vous demandez un transfert ou une excursion, l\'usage des cookies Google et comment modifier votre choix.',
    'privacy.title': 'Politique de confidentialité',
    'privacy.lead': 'Ce que nous collectons lorsque vous utilisez ce site, pourquoi nous le collectons et comment changer d\'avis.',
    'privacy.updated': 'Dernière mise à jour : 1er novembre 2026',
    'privacy.whoHeading': 'Qui nous sommes',
    'privacy.whoBody': 'SG Caribbean Transfers &amp; Tours est une entreprise de transferts privés et d\'excursions basée à Puerto Plata, en République Dominicaine. Pour toute question sur vos données, écrivez à <a href="mailto:sg.caribbeantransferstours@gmail.com">sg.caribbeantransferstours@gmail.com</a> ou contactez-nous sur WhatsApp au +1 829-627-7733.',
    'privacy.collectHeading': 'Ce que nous collectons',
    'privacy.collectIntro': 'Vous pouvez parcourir ce site sans nous donner votre nom. Nous ne recevons des données personnelles que lorsque vous nous envoyez une demande.',
    'privacy.collectWhatsapp': '<strong>Demandes par WhatsApp.</strong> Votre message s\'ouvre dans WhatsApp avec les détails du voyage déjà remplis, et nous recevons ce que vous choisissez d\'envoyer. WhatsApp gère cette conversation selon sa propre politique de confidentialité.',
    'privacy.collectEmail': '<strong>Demandes par email.</strong> Nos formulaires nous transmettent votre nom, votre adresse email, les détails du voyage et votre message via Formspree, et nous les recevons dans notre boîte Gmail.',
    'privacy.collectTrip': '<strong>Détails du voyage.</strong> Selon votre réservation, ils peuvent inclure votre trajet, vos dates, votre numéro de vol, les passagers, les bagages et votre navire de croisière.',
    'privacy.collectCart': '<strong>Votre panier.</strong> Il reste dans votre navigateur jusqu\'à ce que vous l\'envoyiez ou le vidiez. Nous ne le voyons pas avant.',
    'privacy.collectPayment': 'Nous n\'acceptons aucun paiement sur ce site. Vous payez le chauffeur à l\'arrivée.',
    'privacy.useHeading': 'Comment nous les utilisons',
    'privacy.useBody': 'Nous utilisons vos données pour vous répondre, confirmer votre réservation et assurer votre transfert ou votre excursion. Nous ne vendons pas vos données et ne les utilisons pas à des fins de marketing, sauf si vous nous le demandez.',
    'privacy.cookiesHeading': 'Cookies et mesure',
    'privacy.cookiesBody': 'Google Analytics compte les visites et les pages vues, et Google Ads nous indique quelles annonces ont mené à une demande de réservation. Google reçoit des données techniques telles que votre adresse IP, votre appareil, votre navigateur et l\'annonce sur laquelle vous avez cliqué. Nous ne transmettons jamais à Google votre nom, votre adresse email ni vos messages, et nous n\'utilisons pas ces outils pour le remarketing ou les annonces personnalisées.',
    'privacy.cookiesChoice': 'Pour les visiteurs de l\'Espace économique européen, du Royaume-Uni, de la Suisse et du Québec, ces cookies restent désactivés jusqu\'à leur acceptation. Partout ailleurs, ils sont activés et vous pouvez les refuser à tout moment. Si vous les refusez, nous supprimons ceux déjà enregistrés. Google peut encore recevoir un signal de base, sans cookies, indiquant qu\'une page a été chargée ou qu\'une demande a été envoyée.',
    'privacy.tableCaption': 'Cookies et stockage du navigateur sur ce site',
    'privacy.thName': 'Nom',
    'privacy.thSetBy': 'Origine',
    'privacy.thPurpose': 'Finalité',
    'privacy.thLasts': 'Durée',
    'privacy.thisSite': 'Ce site',
    'privacy.gaPurpose': 'Compte les visites et les pages vues',
    'privacy.gaLasts': 'Jusqu\'à 2 ans',
    'privacy.adsPurpose': 'Relie une demande de réservation à l\'annonce qui vous a amené',
    'privacy.adsLasts': 'Jusqu\'à 90 jours',
    'privacy.cartPurpose': 'Conserve votre panier',
    'privacy.cartLasts': 'Jusqu\'à son envoi ou sa suppression',
    'privacy.consentPurpose': 'Mémorise votre choix concernant les cookies',
    'privacy.consentLasts': 'Jusqu\'à ce que vous le modifiiez ou effaciez les données du navigateur',
    'privacy.pickerPurpose': 'Mémorise le service choisi sur la page d\'accueil',
    'privacy.pickerLasts': 'Jusqu\'à la fermeture de l\'onglet',
    'privacy.providersHeading': 'Autres entreprises concernées',
    'privacy.providersIntro': 'Ces entreprises traitent des données lorsque vous utilisez ce site. La plupart sont basées aux États-Unis, vos données peuvent donc être traitées hors de votre pays.',
    'privacy.providerGithub': '<strong>GitHub Pages</strong> héberge ce site et peut enregistrer les adresses IP pour assurer son fonctionnement.',
    'privacy.providerFonts': '<strong>Google Fonts</strong> fournit les polices de caractères : votre navigateur se connecte donc à Google et partage votre adresse IP.',
    'privacy.providerFormspree': '<strong>Formspree</strong> nous transmet les formulaires par email.',
    'privacy.providerGoogle': '<strong>Google et WhatsApp</strong> gèrent l\'email, les messages et la mesure décrits ci-dessus.',
    'privacy.keepHeading': 'Durée de conservation',
    'privacy.keepBody': 'Nous conservons les messages de réservation le temps nécessaire pour gérer votre voyage, répondre aux questions ultérieures et respecter nos obligations légales et comptables.',
    'privacy.rightsHeading': 'Vos choix et vos droits',
    'privacy.rightsBody': 'Vous pouvez nous demander quelles données nous détenons sur vous, et nous demander de les corriger ou de les supprimer, en écrivant à l\'adresse ci-dessus. Vous pouvez modifier votre choix concernant les cookies à tout moment. Selon votre lieu de résidence, vous pouvez aussi avoir le droit de vous opposer à l\'utilisation de vos données, d\'en recevoir une copie et de déposer une plainte auprès de votre autorité de protection des données.',
