const SUPPORTED_LANGS = ['en', 'es', 'fr'];
// The served document is the authority. Every page carries <html lang="..">,
// so a visitor on /es/transfers.html gets Spanish whatever they clicked
// earlier — which is also what a crawler at that URL must see. Staying inside
// a language needs no state: every internal link is relative, so /es/ links
// lead to /es/.
const pageLang = document.documentElement.lang;
let currentLang = SUPPORTED_LANGS.includes(pageLang) ? pageLang : 'en';

/**
 * Looks up a translation key in the active language (falling back to
 * English, then the key itself), interpolating any {token} placeholders.
 * @param {string} key    Dictionary key, e.g. "calc.reserve".
 * @param {Object} [vars] Map of {token: value} substitutions.
 * @returns {string} Translated, interpolated string.
 */
function t(key, vars) {
  let str = I18N[currentLang][key] ?? I18N.en[key] ?? key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) str = str.replaceAll(`{${k}}`, v);
  }
  return str;
}

/** @returns {string} Active language code, "en", "es" or "fr". */
function getLang() {
  return currentLang;
}

/** Re-renders every static [data-i18n] / [data-i18n-attr] element and document meta. */
function applyStaticTranslations() {
  document.documentElement.lang = currentLang;
  const page = document.body.dataset.page || 'home';
  const titleKey = `meta.${page}.title`;
  const descKey = `meta.${page}.description`;
  document.title = t(titleKey);

  document.querySelectorAll('[data-i18n]').forEach((el) => {
    el.innerHTML = t(el.dataset.i18n);
  });

  // Format: data-i18n-attr="attr1:key1|attr2:key2" — lets one element
  // translate several attributes (e.g. aria-label + placeholder) at once.
  document.querySelectorAll('[data-i18n-attr]').forEach((el) => {
    el.dataset.i18nAttr.split('|').forEach((pair) => {
      const [attr, key] = pair.split(':');
      el.setAttribute(attr, t(key));
    });
  });

  const metaDesc = document.querySelector('meta[name="description"]');
  if (metaDesc) metaDesc.setAttribute('content', t(descKey));
  const ogTitle = document.querySelector('meta[property="og:title"]');
  if (ogTitle) ogTitle.setAttribute('content', t(titleKey));
  const ogDesc = document.querySelector('meta[property="og:description"]');
  if (ogDesc) ogDesc.setAttribute('content', t(descKey));

  document.querySelectorAll('.lang-btn').forEach((btn) => {
    const active = btn.dataset.lang === currentLang;
    btn.classList.toggle('is-active', active);
    btn.setAttribute('aria-pressed', String(active));
  });
}

/**
 * Switches the active language in place, without a page load: re-renders the
 * static text and fires 'sariel:langchange' so the feature modules re-render
 * their JS-built content too. The visible switcher navigates between the
 * pre-rendered /es/ and /fr/ URLs instead of calling this, so this is the
 * programmatic path — it is what defines the langchange contract that
 * calculator.js, cart.js, tours.js, shell.js and contact-choice.js consume.
 * @param {string} lang "en", "es" or "fr".
 * @returns {void}
 */
function setLang(lang) {
  if (!SUPPORTED_LANGS.includes(lang) || lang === currentLang) return;
  currentLang = lang;
  applyStaticTranslations();
  document.dispatchEvent(new CustomEvent('sariel:langchange', { detail: { lang } }));
}

// Re-applied even though the served markup already matches: it is a no-op when
// the page and the dictionary agree, and it repairs the page if they ever
// drift. It also renders anything a module injected before this ran.
applyStaticTranslations();
